// pubspec.yaml -> dependencies:  firebase_core: ^3.6.0   cloud_firestore: ^5.4.4
// firebase_options.dart is generated by running:  flutterfire configure
import 'package:cloud_firestore/cloud_firestore.dart';
import 'package:firebase_core/firebase_core.dart';
import 'package:flutter/material.dart';
import 'firebase_options.dart';

Future<void> main() async {
  WidgetsFlutterBinding.ensureInitialized();
  await Firebase.initializeApp(options: DefaultFirebaseOptions.currentPlatform);
  runApp(const EmployeeApp());
}

class EmployeeApp extends StatelessWidget {
  const EmployeeApp({super.key});

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      debugShowCheckedModeBanner: false,
      title: 'Employee Directory',
      theme: ThemeData(colorSchemeSeed: Colors.deepOrange, useMaterial3: true),
      home: const EmployeePage(),
    );
  }
}

class EmployeePage extends StatefulWidget {
  const EmployeePage({super.key});

  @override
  State<EmployeePage> createState() => _EmployeePageState();
}

class _EmployeePageState extends State<EmployeePage> {
  final _formKey = GlobalKey<FormState>();
  final _nameCtrl = TextEditingController();
  final _idCtrl = TextEditingController();
  final _roleCtrl = TextEditingController();
  final _emailCtrl = TextEditingController();
  String _department = 'Development';
  bool _saving = false;

  final CollectionReference _employees =
      FirebaseFirestore.instance.collection('employees');

  Future<void> _addEmployee() async {
    if (!_formKey.currentState!.validate()) return;
    setState(() => _saving = true);
    try {
      await _employees.add({
        'name': _nameCtrl.text.trim(),
        'nameLower': _nameCtrl.text.trim().toLowerCase(), // used for search
        'empId': _idCtrl.text.trim().toUpperCase(),
        'department': _department,
        'designation': _roleCtrl.text.trim(),
        'email': _emailCtrl.text.trim(),
        'createdAt': FieldValue.serverTimestamp(),
      });
      for (final c in [_nameCtrl, _idCtrl, _roleCtrl, _emailCtrl]) {
        c.clear();
      }
      _showMessage('Employee saved to Firestore');
    } catch (e) {
      _showMessage('Error: $e');
    } finally {
      if (mounted) setState(() => _saving = false);
    }
  }

  void _showMessage(String msg) =>
      ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text(msg)));

  Widget _field(TextEditingController c, String label) => TextFormField(
        controller: c,
        decoration: InputDecoration(
            labelText: label, border: const OutlineInputBorder(), isDense: true),
        validator: (v) => v!.trim().isEmpty ? 'Required' : null,
      );

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: const Text('Employee Directory'),
        backgroundColor: Theme.of(context).colorScheme.primaryContainer,
      ),
      body: Column(
        children: [
          Form(
            key: _formKey,
            child: Padding(
              padding: const EdgeInsets.all(16),
              child: Column(
                children: [
                  Row(children: [
                    Expanded(flex: 3, child: _field(_nameCtrl, 'Name')),
                    const SizedBox(width: 10),
                    Expanded(flex: 2, child: _field(_idCtrl, 'Employee ID')),
                  ]),
                  const SizedBox(height: 10),
                  Row(children: [
                    Expanded(child: _field(_roleCtrl, 'Designation')),
                    const SizedBox(width: 10),
                    Expanded(
                      child: DropdownButtonFormField<String>(
                        value: _department,
                        isDense: true,
                        decoration: const InputDecoration(
                            labelText: 'Department',
                            border: OutlineInputBorder(),
                            isDense: true),
                        items: ['Development', 'Testing', 'Design', 'HR', 'Marketing']
                            .map((d) => DropdownMenuItem(value: d, child: Text(d)))
                            .toList(),
                        onChanged: (v) => setState(() => _department = v!),
                      ),
                    ),
                  ]),
                  const SizedBox(height: 10),
                  TextFormField(
                    controller: _emailCtrl,
                    decoration: const InputDecoration(
                        labelText: 'Email',
                        border: OutlineInputBorder(),
                        isDense: true),
                    validator: (v) =>
                        v!.contains('@') ? null : 'Enter a valid email',
                  ),
                  const SizedBox(height: 12),
                  SizedBox(
                    width: double.infinity,
                    child: FilledButton.icon(
                      onPressed: _saving ? null : _addEmployee,
                      icon: const Icon(Icons.cloud_upload),
                      label: Text(_saving ? 'Saving...' : 'Save to Firestore'),
                    ),
                  ),
                ],
              ),
            ),
          ),
          const Divider(height: 1),
          // Live list: reads the 'employees' collection from the cloud
          Expanded(
            child: StreamBuilder<QuerySnapshot>(
              stream: _employees.orderBy('createdAt', descending: true).snapshots(),
              builder: (context, snapshot) {
                if (snapshot.hasError) {
                  return Center(child: Text('Error: ${snapshot.error}'));
                }
                if (!snapshot.hasData) {
                  return const Center(child: CircularProgressIndicator());
                }
                final docs = snapshot.data!.docs;
                if (docs.isEmpty) {
                  return const Center(child: Text('No employees stored yet'));
                }
                return ListView.builder(
                  padding: const EdgeInsets.all(12),
                  itemCount: docs.length,
                  itemBuilder: (context, i) {
                    final e = docs[i].data() as Map<String, dynamic>;
                    return Card(
                      child: ListTile(
                        leading: CircleAvatar(child: Text(e['name'][0])),
                        title: Text(e['name']),
                        subtitle: Text('${e['designation']} • ${e['department']}'),
                        trailing: Text(e['empId'],
                            style: const TextStyle(fontWeight: FontWeight.bold)),
                      ),
                    );
                  },
                );
              },
            ),
          ),
        ],
      ),
    );
  }
}
